server/index.ts.content:
import express, { type Request, Response, NextFunction } from "express";
import helmet from "helmet";
import rateLimit from "express-rate-limit";
import path from "path";
import { registerRoutes } from "./routes";
import { setupVite, serveStatic, log } from "./vite";
import { createEmailTransporter } from "./email";

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: false, // keep false for GLB/USDZ/CDN
  crossOriginResourcePolicy: { policy: "cross-origin" },
}));

// CORS middleware
const allowedOrigins = process.env.CORS_ORIGIN?.split(",") || [
  'https://moduvo.to',
  'https://www.moduvo.to',
  'http://localhost:5000',
  'http://localhost:3000'
];

app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (allowedOrigins.includes(origin as string)) {
    res.setHeader('Access-Control-Allow-Origin', origin as string);
  }

  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.setHeader('Access-Control-Allow-Credentials', 'true');

  if (req.method === 'OPTIONS') {
    res.sendStatus(200);
  } else {
    next();
  }
});

// Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 600 // limit each IP to 600 requests per windowMs
}));

// Health check endpoint
app.get("/healthz", (_req, res) => res.status(200).send("ok"));

app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: false, limit: '10mb' }));

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  const server = await registerRoutes(app);

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    res.status(status).json({ message });
    throw err;
  });

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get("env") === "development") {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // Initialize email transporter on startup
  if (process.env.NODE_ENV === 'production') {
    try {
      await createEmailTransporter();
      log("Email system initialized successfully");
    } catch (error) {
      log(`Email system initialization failed: ${error}`);
    }
  }

  // Serve static files in production
  if (process.env.NODE_ENV === 'production') {
    app.use(express.static(path.join(__dirname, "../../client/dist")));
    app.get("*", (_req, res) => {
      res.sendFile(path.join(__dirname, "../../client/dist/index.html"));
    });
  }

  // ALWAYS serve the app on the port specified in the environment variable PORT
  // Other ports are firewalled. Default to 5000 if not specified.
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = parseInt(process.env.PORT || '5000', 10);
  server.listen({
    port,
    host: "0.0.0.0",
    reusePort: true,
  }, () => {
    log(`serving on port ${port}`);
  });
})();

server/objectStorage.ts.content:
import { Storage, File } from "@google-cloud/storage";
import { Response } from "express";
import { randomUUID } from "crypto";

const REPLIT_SIDECAR_ENDPOINT = "http://127.0.0.1:1106";

// The object storage client is used to interact with the object storage service.
export const objectStorageClient = new Storage({
  credentials: {
    audience: "replit",
    subject_token_type: "access_token",
    token_url: `${REPLIT_SIDECAR_ENDPOINT}/token`,
    type: "external_account",
    credential_source: {
      url: `${REPLIT_SIDECAR_ENDPOINT}/credential`,
      format: {
        type: "json",
        subject_token_field_name: "access_token",
      },
    },
    universe_domain: "googleapis.com",
  },
  projectId: "",
});

export class ObjectNotFoundError extends Error {
  constructor() {
    super("Object not found");
    this.name = "ObjectNotFoundError";
    Object.setPrototypeOf(this, ObjectNotFoundError.prototype);
  }
}

// The object storage service is used to interact with the object storage service.
export class ObjectStorageService {
  constructor() {}

  // Gets the public object search paths.
  getPublicObjectSearchPaths(): Array<string> {
    const pathsStr = process.env.PUBLIC_OBJECT_SEARCH_PATHS || "";
    const paths = Array.from(
      new Set(
        pathsStr
          .split(",")
          .map((path) => path.trim())
          .filter((path) => path.length > 0)
      )
    );
    if (paths.length === 0) {
      throw new Error(
        "PUBLIC_OBJECT_SEARCH_PATHS not set. Create a bucket in 'Object Storage' " +
          "tool and set PUBLIC_OBJECT_SEARCH_PATHS env var (comma-separated paths)."
      );
    }
    return paths;
  }

  // Gets the private object directory.
  getPrivateObjectDir(): string {
    const dir = process.env.PRIVATE_OBJECT_DIR || "";
    if (!dir) {
      throw new Error(
        "PRIVATE_OBJECT_DIR not set. Create a bucket in 'Object Storage' " +
          "tool and set PRIVATE_OBJECT_DIR env var."
      );
    }
    return dir;
  }

  // Search for a public object from the search paths.
  async searchPublicObject(filePath: string): Promise<File | null> {
    for (const searchPath of this.getPublicObjectSearchPaths()) {
      const fullPath = `${searchPath}/${filePath}`;

      // Full path format: /<bucket_name>/<object_name>
      const { bucketName, objectName } = parseObjectPath(fullPath);
      const bucket = objectStorageClient.bucket(bucketName);
      const file = bucket.file(objectName);

      // Check if file exists
      const [exists] = await file.exists();
      if (exists) {
        return file;
      }
    }

    return null;
  }

  // Downloads an object to the response.
  async downloadObject(file: File, res: Response, cacheTtlSec: number = 3600) {
    try {
      // Get file metadata
      const [metadata] = await file.getMetadata();

      // Set appropriate headers
      res.set({
        "Content-Type": metadata.contentType || "application/octet-stream",
        "Content-Length": metadata.size,
        "Cache-Control": `public, max-age=${cacheTtlSec}`,
      });

      // Stream the file to the response
      const stream = file.createReadStream();

      stream.on("error", (err) => {
        console.error("Stream error:", err);
        if (!res.headersSent) {
          res.status(500).json({ error: "Error streaming file" });
        }
      });

      stream.pipe(res);
    } catch (error) {
      console.error("Error downloading file:", error);
      if (!res.headersSent) {
        res.status(500).json({ error: "Error downloading file" });
      }
    }
  }

  // Gets the upload URL for a public object.
  async getPublicUploadURL(fileName: string): Promise<string> {
    const publicSearchPaths = this.getPublicObjectSearchPaths();
    if (publicSearchPaths.length === 0) {
      throw new Error("No public object search paths configured");
    }

    // Use the first search path for uploads
    const uploadPath = `${publicSearchPaths[0]}/${fileName}`;
    const { bucketName, objectName } = parseObjectPath(uploadPath);

    // Sign URL for PUT method with TTL
    return signObjectURL({
      bucketName,
      objectName,
      method: "PUT",
      ttlSec: 900,
    });
  }
}

function parseObjectPath(path: string): {
  bucketName: string;
  objectName: string;
} {
  if (!path.startsWith("/")) {
    path = `/${path}`;
  }
  const pathParts = path.split("/");
  if (pathParts.length < 3) {
    throw new Error("Invalid path: must contain at least a bucket name");
  }

  const bucketName = pathParts[1];
  const objectName = pathParts.slice(2).join("/");

  return {
    bucketName,
    objectName,
  };
}

async function signObjectURL({
  bucketName,
  objectName,
  method,
  ttlSec,
}: {
  bucketName: string;
  objectName: string;
  method: "GET" | "PUT" | "DELETE" | "HEAD";
  ttlSec: number;
}): Promise<string> {
  const request = {
    bucket_name: bucketName,
    object_name: objectName,
    method,
    expires_at: new Date(Date.now() + ttlSec * 1000).toISOString(),
  };
  const response = await fetch(
    `${REPLIT_SIDECAR_ENDPOINT}/object-storage/signed-object-url`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(request),
    }
  );
  if (!response.ok) {
    throw new Error(
      `Failed to sign object URL, errorcode: ${response.status}, ` +
        `make sure you're running on Replit`
    );
  }

  const { signed_url: signedURL } = await response.json();
  return signedURL;
}

server/replitAuth.ts.content:
import * as client from "openid-client";
import { Strategy, type VerifyFunction } from "openid-client/passport";

import passport from "passport";
import session from "express-session";
import type { Express, RequestHandler } from "express";
import memoize from "memoizee";
import connectPg from "connect-pg-simple";
import { storage } from "./storage";

if (!process.env.REPLIT_DOMAINS) {
  throw new Error("Environment variable REPLIT_DOMAINS not provided");
}

const getOidcConfig = memoize(
  async () => {
    return await client.discovery(
      new URL(process.env.ISSUER_URL ?? "https://replit.com/oidc"),
      process.env.REPL_ID!
    );
  },
  { maxAge: 3600 * 1000 }
);

export function getSession() {
  const sessionTtl = 7 * 24 * 60 * 60 * 1000; // 1 week
  const pgStore = connectPg(session);
  const sessionStore = new pgStore({
    conString: process.env.DATABASE_URL,
    createTableIfMissing: false,
    ttl: sessionTtl,
    tableName: "sessions",
  });
  return session({
    secret: process.env.SESSION_SECRET!,
    store: sessionStore,
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      secure: true,
      maxAge: sessionTtl,
    },
  });
}

function updateUserSession(
  user: any,
  tokens: client.TokenEndpointResponse & client.TokenEndpointResponseHelpers
) {
  user.claims = tokens.claims();
  user.access_token = tokens.access_token;
  user.refresh_token = tokens.refresh_token;
  user.expires_at = user.claims?.exp;
}

async function upsertUser(
  claims: any,
) {
  await storage.upsertUser({
    id: claims["sub"],
    email: claims["email"],
    firstName: claims["first_name"],
    lastName: claims["last_name"],
    profileImageUrl: claims["profile_image_url"],
  });
}

export async function setupAuth(app: Express) {
  app.set("trust proxy", 1);
  app.use(getSession());
  app.use(passport.initialize());
  app.use(passport.session());

  const config = await getOidcConfig();

  const verify: VerifyFunction = async (
    tokens: client.TokenEndpointResponse & client.TokenEndpointResponseHelpers,
    verified: passport.AuthenticateCallback
  ) => {
    const user = {};
    updateUserSession(user, tokens);
    await upsertUser(tokens.claims());
    verified(null, user);
  };

  for (const domain of process.env
    .REPLIT_DOMAINS!.split(",")) {
    const strategy = new Strategy(
      {
        name: `replitauth:${domain}`,
        config,
        scope: "openid email profile offline_access",
        callbackURL: `https://${domain}/api/callback`,
      },
      verify,
    );
    passport.use(strategy);
  }

  passport.serializeUser((user: Express.User, cb) => cb(null, user));
  passport.deserializeUser((user: Express.User, cb) => cb(null, user));

  app.get("/api/login", (req, res, next) => {
    passport.authenticate(`replitauth:${req.hostname}`, {
      prompt: "login consent",
      scope: ["openid", "email", "profile", "offline_access"],
    })(req, res, next);
  });

  app.get("/api/callback", (req, res, next) => {
    passport.authenticate(`replitauth:${req.hostname}`, {
      successReturnToOrRedirect: "/",
      failureRedirect: "/api/login",
    })(req, res, next);
  });

  app.get("/api/logout", (req, res) => {
    req.logout(() => {
      res.redirect(
        client.buildEndSessionUrl(config, {
          client_id: process.env.REPL_ID!,
          post_logout_redirect_uri: `${req.protocol}://${req.hostname}`,
        }).href
      );
    });
  });
}

export const isAuthenticated: RequestHandler = async (req, res, next) => {
  const user = req.user as any;

  if (!req.isAuthenticated() || !user.expires_at) {
    return res.status(401).json({ message: "Unauthorized" });
  }

  const now = Math.floor(Date.now() / 1000);
  if (now <= user.expires_at) {
    return next();
  }

  const refreshToken = user.refresh_token;
  if (!refreshToken) {
    res.status(401).json({ message: "Unauthorized" });
    return;
  }

  try {
    const config = await getOidcConfig();
    const tokenResponse = await client.refreshTokenGrant(config, refreshToken);
    updateUserSession(user, tokenResponse);
    return next();
  } catch (error) {
    res.status(401).json({ message: "Unauthorized" });
    return;
  }
};

server/routes.ts.content:
import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { setupAuth, isAuthenticated } from "./replitAuth";
import { requireAuth, requireAdmin, type AuthenticatedRequest } from "./middleware/auth";
import { sendQuoteEmail } from "./email";
import { insertQuoteSchema, insertDesignSchema } from "@shared/schema";
import { z } from "zod";
import { ObjectStorageService, ObjectNotFoundError } from "./objectStorage";

// Deterministic pricing configuration - production values
const LABOUR_HOURS = { shelf: 0.25, drawer: 0.5, door: 0.4, rail: 0.15 };
const LABOUR_RATE = 85; // CAD per hour
const FINISH_MULTIPLIER = { white: 1.0, matte: 1.08, wood: 1.12, glass: 1.18 };
const DELIVERY_ZONES = {
  TORONTO: { fee: 75 },
  GTA: { fee: 125 },
  ONTARIO: { fee: 195 },
  OOP: { fee: 295 }
};
const MIN_ORDER = 1200;

// Enhanced quote calculation with deterministic pricing
function calculateQuote(configuration: any, location?: string) {
  let materialsPrice = parseFloat(configuration.basePrice || "0");
  let laborHours = 4; // Base installation time
  let installationFee = 0; // Additional service fees

  // Realistic component-based pricing and labor
  if (configuration.selectedComponents) {
    for (const component of configuration.selectedComponents) {
      const componentPrice = parseFloat(component.price || "0");
      materialsPrice += componentPrice;

      // Realistic labor time based on component complexity
      switch (component.category) {
        case 'hanging_rail':
          laborHours += 0.25;
          break;
        case 'drawer':
          laborHours += 0.75; // Drawers require more installation time
          break;
        case 'shelf':
          laborHours += 0.33;
          break;
        case 'lighting':
          laborHours += 1.0; // Electrical work takes longer
          installationFee += 50; // Additional electrical service fee
          break;
        case 'door':
          laborHours += 1.25; // Doors require precise alignment
          break;
        default:
          laborHours += 0.5;
      }
    }
  }

  // Apply finish multiplier with realistic material cost impacts
  if (configuration.finish?.priceMultiplier) {
    const multiplier = parseFloat(configuration.finish.priceMultiplier);
    materialsPrice *= multiplier;

    // Premium finishes require more careful installation
    if (multiplier > 1.5) {
      laborHours += 1.0; // Premium finishes need extra care
    }
  }

  // Calculate labor cost with realistic rates
  const laborRate = 85; // Increased to reflect skilled craftsmanship
  const laborPrice = laborHours * laborRate;

  // Enhanced delivery calculation based on distance and complexity
  let deliveryPrice = 175; // Base delivery fee increased
  if (location) {
    const loc = location.toLowerCase();
    if (!loc.includes('toronto') && !loc.includes('gta')) {
      deliveryPrice += 125; // Higher fee for outside GTA

      // Additional fees for very remote locations
      if (loc.includes('ottawa') || loc.includes('montreal') || loc.includes('kingston')) {
        deliveryPrice += 75; // Major cities but distant
      } else if (!loc.includes('ontario')) {
        deliveryPrice += 200; // Out of province
      }
    }
  }

  // Add complexity-based installation fee
  const totalComponents = configuration.selectedComponents?.length || 0;
  if (totalComponents > 8) {
    installationFee += 100; // Complex configuration fee
  }

  const subtotal = materialsPrice + laborPrice + deliveryPrice + installationFee;

  // Apply 38% profit margin: Price = Cost / (1 - 0.38)
  const totalPrice = subtotal / 0.62;

  // Add minimum order value
  const minimumOrderValue = 1200;
  const finalPrice = Math.max(totalPrice, minimumOrderValue);

  return {
    materialsPrice: materialsPrice.toFixed(2),
    laborPrice: laborPrice.toFixed(2),
    deliveryPrice: deliveryPrice.toFixed(2),
    installationFee: installationFee.toFixed(2),
    totalPrice: finalPrice.toFixed(2),
    laborHours: laborHours.toFixed(1),
  };
}

// Send quote email
async function sendQuoteEmail(quote: any, configuration: any) {
  const emailHtml = `
    <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; background-color: #FDFCF9; padding: 20px; border-radius: 8px;">
      <h1 style="color: #C3D5CA; text-align: center; font-family: Arial, sans-serif;">Your Moduvo Quote</h1>
      <p>Dear ${quote.customerName},</p>
      <p style="color: #555555;">Thank you for your interest in Moduvo's luxury modular storage solutions. Please find your detailed quote below:</p>

      <div style="background: #D8CEC4; padding: 20px; border-radius: 8px; margin: 20px 0; color: #2B2B2B;">
        <h3 style="color: #2B2B2B;">Configuration Details</h3>
        <p><strong>Product:</strong> ${configuration.productName}</p>
        <p><strong>Dimensions:</strong> ${configuration.dimensions?.width}cm × ${configuration.dimensions?.height}cm × ${configuration.dimensions?.depth}cm</p>
        <p><strong>Finish:</strong> ${configuration.finish?.name}</p>
      </div>

      <div style="background: #D8CEC4; padding: 20px; border-radius: 8px; margin: 20px 0; color: #2B2B2B;">
        <h3 style="color: #2B2B2B;">Price Breakdown</h3>
        <p><strong>Materials:</strong> $${quote.materialsPrice}</p>
        <p><strong>Labor & Installation (${quote.laborHours} hours):</strong> $${quote.laborPrice}</p>
        <p><strong>Delivery:</strong> $${quote.deliveryPrice}</p>
        ${quote.installationFee && parseFloat(quote.installationFee) > 0 ? `<p><strong>Installation Fees:</strong> $${quote.installationFee}</p>` : ''}
        <hr>
        <p style="font-size: 18px; font-weight: bold; color: #C3D5CA;">Total: $${quote.totalPrice}</p>
      </div>

      <p style="color: #555555;">This quote is valid for 30 days. A Moduvo representative will contact you within 24 hours to discuss next steps and schedule a consultation if needed.</p>

      <p style="color: #555555;">Best regards,<br><span style="color: #C8A97E; font-weight: bold;">The Moduvo Team</span></p>
    </div>
  `;

  await transporter.sendMail({
    from: process.env.FROM_EMAIL || "quotes@moduvo.com",
    to: quote.customerEmail,
    subject: "Your Moduvo Custom Quote",
    html: emailHtml,
  });
}

export async function registerRoutes(app: Express): Promise<Server> {
  // Auth middleware
  await setupAuth(app);

  // Auth routes
  app.get('/api/auth/user', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      res.json(user);
    } catch (error) {
      console.error("Error fetching user:", error);
      res.status(500).json({ message: "Failed to fetch user" });
    }
  });

  // Product routes
  app.get('/api/products', async (req, res) => {
    try {
      const products = await storage.getProducts();
      res.json(products);
    } catch (error) {
      console.error("Error fetching products:", error);
      res.status(500).json({ message: "Failed to fetch products" });
    }
  });

  app.get('/api/components', async (req, res) => {
    try {
      const components = await storage.getComponents();
      res.json(components);
    } catch (error) {
      console.error("Error fetching components:", error);
      res.status(500).json({ message: "Failed to fetch components" });
    }
  });

  app.get('/api/finishes', async (req, res) => {
    try {
      const finishes = await storage.getFinishes();
      res.json(finishes);
    } catch (error) {
      console.error("Error fetching finishes:", error);
      res.status(500).json({ message: "Failed to fetch finishes" });
    }
  });

  // Quote calculation
  app.post('/api/quote/calculate', async (req, res) => {
    try {
      const { configuration, location } = req.body;
      const quote = calculateQuote(configuration, location);
      res.json(quote);
    } catch (error) {
      console.error("Error calculating quote:", error);
      res.status(500).json({ message: "Failed to calculate quote" });
    }
  });

  // Create and send quote
  app.post('/api/quotes', async (req, res) => {
    try {
      const quoteData = insertQuoteSchema.parse(req.body);

      // Calculate pricing
      const pricing = calculateQuote(req.body.configuration, quoteData.installationAddress || undefined);

      const quote = await storage.createQuote({
        ...quoteData,
        materialsPrice: pricing.materialsPrice,
        laborPrice: pricing.laborPrice,
        deliveryPrice: pricing.deliveryPrice,
        installationFee: pricing.installationFee,
        totalPrice: pricing.totalPrice,
      });

      // Send email using new email service
      await sendQuoteEmail(quote, req.body.configuration);

      // Update quote as sent
      await storage.updateQuote(quote.id, { status: 'sent', sentAt: new Date() });

      res.json(quote);
    } catch (error) {
      console.error("Error creating quote:", error);
      res.status(500).json({ message: "Failed to create quote" });
    }
  });

  // Protected design routes
  app.get('/api/designs', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const designs = await storage.getUserDesigns(userId);
      res.json(designs);
    } catch (error) {
      console.error("Error fetching designs:", error);
      res.status(500).json({ message: "Failed to fetch designs" });
    }
  });

  app.post('/api/designs', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const designData = insertDesignSchema.parse({
        ...req.body,
        userId,
      });

      const design = await storage.createDesign(designData);
      res.json(design);
    } catch (error) {
      console.error("Error creating design:", error);
      res.status(500).json({ message: "Failed to create design" });
    }
  });

  app.get('/api/designs/:id', isAuthenticated, async (req: any, res) => {
    try {
      const design = await storage.getDesign(req.params.id);
      if (!design) {
        return res.status(404).json({ message: "Design not found" });
      }

      // Check ownership
      const userId = req.user.claims.sub;
      if (design.userId !== userId) {
        return res.status(403).json({ message: "Access denied" });
      }

      res.json(design);
    } catch (error) {
      console.error("Error fetching design:", error);
      res.status(500).json({ message: "Failed to fetch design" });
    }
  });

  app.put('/api/designs/:id', isAuthenticated, async (req: any, res) => {
    try {
      const design = await storage.getDesign(req.params.id);
      if (!design) {
        return res.status(404).json({ message: "Design not found" });
      }

      // Check ownership
      const userId = req.user.claims.sub;
      if (design.userId !== userId) {
        return res.status(403).json({ message: "Access denied" });
      }

      const updated = await storage.updateDesign(req.params.id, req.body);
      res.json(updated);
    } catch (error) {
      console.error("Error updating design:", error);
      res.status(500).json({ message: "Failed to update design" });
    }
  });

  app.delete('/api/designs/:id', isAuthenticated, async (req: any, res) => {
    try {
      const design = await storage.getDesign(req.params.id);
      if (!design) {
        return res.status(404).json({ message: "Design not found" });
      }

      // Check ownership
      const userId = req.user.claims.sub;
      if (design.userId !== userId) {
        return res.status(403).json({ message: "Access denied" });
      }

      const deleted = await storage.deleteDesign(req.params.id);
      res.json({ success: deleted });
    } catch (error) {
      console.error("Error deleting design:", error);
      res.status(500).json({ message: "Failed to delete design" });
    }
  });

  // User quotes
  app.get('/api/quotes', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const quotes = await storage.getUserQuotes(userId);
      res.json(quotes);
    } catch (error) {
      console.error("Error fetching quotes:", error);
      res.status(500).json({ message: "Failed to fetch quotes" });
    }
  });

  // Admin middleware function
  const isAdmin = async (req: any, res: any, next: any) => {
    if (!req.isAuthenticated() || !req.user?.claims?.sub) {
      return res.status(401).json({ message: "Unauthorized" });
    }

    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!user || (user.role !== 'admin' && user.role !== 'staff')) {
        return res.status(403).json({ message: "Admin access required" });
      }

      next();
    } catch (error) {
      console.error("Error checking admin role:", error);
      res.status(500).json({ message: "Authorization check failed" });
    }
  };

  // Admin routes - protected with admin role check
  app.get('/api/admin/quotes', isAuthenticated, isAdmin, async (req: any, res) => {
    try {
      const quotes = await storage.getAllQuotes();
      res.json(quotes);
    } catch (error) {
      console.error("Error fetching admin quotes:", error);
      res.status(500).json({ message: "Failed to fetch quotes" });
    }
  });

  app.put('/api/admin/quotes/:id', isAuthenticated, isAdmin, async (req: any, res) => {
    try {
      const updated = await storage.updateQuote(req.params.id, req.body);
      res.json(updated);
    } catch (error) {
      console.error("Error updating quote:", error);
      res.status(500).json({ message: "Failed to update quote" });
    }
  });

  app.get('/api/admin/designs', isAuthenticated, isAdmin, async (req: any, res) => {
    try {
      const designs = await storage.getAllDesigns();
      res.json(designs);
    } catch (error) {
      console.error("Error fetching admin designs:", error);
      res.status(500).json({ message: "Failed to fetch designs" });
    }
  });

  // Initialize default data if needed
  app.post('/api/init-data', async (req, res) => {
    try {
      // Create default products, components, and finishes
      const products = await storage.getProducts();
      if (products.length === 0) {
        await storage.createProduct({
          name: "Modular Wardrobe System",
          description: "Premium modular wardrobe with customizable components",
          category: "wardrobe",
          basePrice: "2499.00",
          modelUrl: "https://storage.googleapis.com/models/wardrobe.glb",
          imageUrl: "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=800",
          isActive: true,
        });

        await storage.createComponent({
          name: "Hanging Rail",
          description: "Premium hanging rail for clothes",
          price: "89.00",
          category: "hanging_rail",
          isActive: true,
        });

        await storage.createComponent({
          name: "Drawer Set (3)",
          description: "Set of 3 premium drawers",
          price: "245.00",
          category: "drawer",
          isActive: true,
        });

        await storage.createFinish({
          name: "Pure White",
          color: "#FFFFFF",
          priceMultiplier: "1.00",
          isActive: true,
        });

        await storage.createFinish({
          name: "Oak Wood",
          color: "#D2B48C",
          priceMultiplier: "1.25",
          isActive: true,
        });
      }

      res.json({ success: true });
    } catch (error) {
      console.error("Error initializing data:", error);
      res.status(500).json({ message: "Failed to initialize data" });
    }
  });

  // Object storage routes for public file serving and uploading
  app.get("/public-objects/:filePath(*)", async (req, res) => {
    const filePath = req.params.filePath;
    const objectStorageService = new ObjectStorageService();
    try {
      const file = await objectStorageService.searchPublicObject(filePath);
      if (!file) {
        return res.status(404).json({ error: "File not found" });
      }
      objectStorageService.downloadObject(file, res);
    } catch (error) {
      console.error("Error searching for public object:", error);
      return res.status(500).json({ error: "Internal server error" });
    }
  });

  // Get upload URL for gallery images
  app.post("/api/gallery/upload", isAuthenticated, async (req, res) => {
    const { fileName } = req.body;
    if (!fileName) {
      return res.status(400).json({ error: "fileName is required" });
    }

    try {
      const objectStorageService = new ObjectStorageService();
      // Add a timestamp to prevent filename conflicts
      const timestamp = Date.now();
      const fileExtension = fileName.split('.').pop();
      const uniqueFileName = `gallery-${timestamp}.${fileExtension}`;

      const uploadURL = await objectStorageService.getPublicUploadURL(uniqueFileName);

      res.json({ 
        uploadURL,
        publicPath: `/public-objects/${uniqueFileName}`
      });
    } catch (error) {
      console.error("Error getting upload URL:", error);
      res.status(500).json({ error: "Failed to get upload URL" });
    }
  });

  const httpServer = createServer(app);
  return httpServer;
}

