import nodemailer from "nodemailer";

let transporter: nodemailer.Transporter | null = null;

export async function createEmailTransporter() {
  if (transporter) return transporter;

  transporter = nodemailer.createTransport({
    host: process.env.SMTP_HOST!,
    port: Number(process.env.SMTP_PORT || 587),
    secure: false, // STARTTLS
    auth: {
      user: process.env.SMTP_USER!,
      pass: process.env.SMTP_PASS!,
    },
  });

  try {
    await transporter.verify();
    console.log("Email transporter verified successfully");
  } catch (error) {
    console.error("Email transporter verification failed:", error);
    throw error;
  }

  return transporter;
}

export async function sendQuoteEmail(quote: any, configuration: any) {
  const transporter = await createEmailTransporter();

  const laborHours = calculateLaborHours(configuration);

  const emailHtml = `
    <div style="font-family: 'Georgia', serif; max-width: 600px; margin: 0 auto; background: #FEFEFE; color: #2B2B2B;">
      <div style="background: linear-gradient(135deg, #D4AF37 0%, #C3A028 100%); padding: 40px 30px; text-align: center;">
        <h1 style="margin: 0; color: #FEFEFE; font-size: 32px; font-weight: 300; letter-spacing: 2px;">MODUVO</h1>
        <p style="margin: 10px 0 0; color: #FEFEFE; font-size: 16px; opacity: 0.9;">Custom Storage Solutions</p>
      </div>

      <div style="padding: 30px;">
        <h2 style="color: #2B2B2B; font-size: 24px; margin-bottom: 20px;">Your Custom Quote</h2>
        <p style="font-size: 16px; line-height: 1.6; margin-bottom: 20px;">Dear ${quote.customerName},</p>
        <p style="font-size: 16px; line-height: 1.6; margin-bottom: 30px;">
          Thank you for your interest in Moduvo's luxury modular storage solutions. We've prepared a custom quote based on your configuration.
        </p>

        <div style="background: #F8F6F0; padding: 20px; border-radius: 8px; margin: 20px 0;">
          <h3 style="color: #2B2B2B;">Configuration Details</h3>
          <p><strong>Product:</strong> ${configuration.product?.name || 'Custom Configuration'}</p>
          <p><strong>Dimensions:</strong> ${configuration.width || 'Custom'} × ${configuration.height || 'Custom'} × ${configuration.depth || 'Custom'}</p>
          <p><strong>Components:</strong> ${configuration.components?.map((c: any) => c.name).join(', ') || 'Standard'}</p>
          <p><strong>Finish:</strong> ${configuration.finish?.name || 'Standard'}</p>
        </div>

        <div style="background: #D8CEC4; padding: 20px; border-radius: 8px; margin: 20px 0; color: #2B2B2B;">
          <h3 style="color: #2B2B2B;">Price Breakdown</h3>
          <p><strong>Materials:</strong> $${quote.materialsPrice}</p>
          <p><strong>Labor & Installation (${laborHours} hours):</strong> $${quote.laborPrice}</p>
          <p><strong>Delivery:</strong> $${quote.deliveryPrice}</p>
          ${quote.installationFee && parseFloat(quote.installationFee) > 0 ? `<p><strong>Installation Fees:</strong> $${quote.installationFee}</p>` : ''}
          <hr>
          <p style="font-size: 18px; font-weight: bold; color: #C3D5CA;">Total: $${quote.totalPrice}</p>
        </div>

        <div style="background: #F8F6F0; padding: 20px; border-radius: 8px; margin: 20px 0;">
          <h3 style="color: #2B2B2B;">Next Steps</h3>
          <p>Our team will contact you within 24 hours to discuss:</p>
          <ul style="padding-left: 20px;">
            <li>Design refinements and customizations</li>
            <li>Installation timeline and scheduling</li>
            <li>Payment options and terms</li>
            <li>Any questions about your configuration</li>
          </ul>
        </div>

        <p style="font-size: 16px; line-height: 1.6; margin-top: 30px;">
          Thank you for choosing Moduvo for your luxury storage needs.
        </p>

        <p style="font-size: 14px; color: #666; margin-top: 30px;">
          <strong>Moduvo</strong><br>
          Luxury Modular Storage Solutions<br>
          quotes@moduvo.to | moduvo.to
        </p>
      </div>
    </div>
  `;

  const mailOptions = {
    from: process.env.FROM_EMAIL!,
    to: quote.customerEmail,
    subject: `Your Moduvo Quote - $${quote.totalPrice}`,
    html: emailHtml,
  };

  await transporter.sendMail(mailOptions);
}

function calculateLaborHours(configuration: any): number {
  const LABOUR_HOURS = { shelf: 0.25, drawer: 0.5, door: 0.4, rail: 0.15 };

  let totalHours = 1; // Base assembly time

  if (configuration.components) {
    configuration.components.forEach((component: any) => {
      const type = component.type?.toLowerCase();
      totalHours += LABOUR_HOURS[type as keyof typeof LABOUR_HOURS] || 0.25;
    });
  }

  return Math.round(totalHours * 100) / 100;
}

